package orchestrator

import (
	"context"
	"encoding/json"
	"fmt"
	"net"
	"net/http"
	"strings"
	"sync"
	"time"
)

type CircuitState int

const (
	StateClosed CircuitState = iota
	StateOpen
	StateHalfOpen
)

type CircuitBreaker struct {
	mu           sync.RWMutex
	state        CircuitState
	failures     int
	threshold    int
	resetTimeout time.Duration
	lastFailure  time.Time
}

func NewCircuitBreaker(threshold int, resetTimeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:        StateClosed,
		threshold:    threshold,
		resetTimeout: resetTimeout,
	}
}

func (cb *CircuitBreaker) Allow() bool {
	cb.mu.RLock()
	defer cb.mu.RUnlock()
	switch cb.state {
	case StateClosed:
		return true
	case StateOpen:
		if time.Since(cb.lastFailure) > cb.resetTimeout {
			return true
		}
		return false
	case StateHalfOpen:
		return true
	}
	return false
}

func (cb *CircuitBreaker) RecordSuccess() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures = 0
	cb.state = StateClosed
}

func (cb *CircuitBreaker) RecordFailure() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures++
	cb.lastFailure = time.Now()
	if cb.failures >= cb.threshold {
		cb.state = StateOpen
	}
}

type ServiceEndpoint struct {
	Host       string `json:"host"`
	Port       int    `json:"port"`
	HealthPath string `json:"health_path"`
}

type ContainerOrchestrator struct {
	allowedNetworks []*net.IPNet
	breakers        map[string]*CircuitBreaker
	mu              sync.RWMutex
	httpClient      *http.Client
	resolvedCache   map[string]net.IP
	cacheMu         sync.RWMutex
}

func NewContainerOrchestrator() *ContainerOrchestrator {
	_, private10, _ := net.ParseCIDR("10.0.0.0/8")
	_, private172, _ := net.ParseCIDR("172.16.0.0/12")
	_, private192, _ := net.ParseCIDR("192.168.0.0/16")

	dialer := &net.Dialer{Timeout: 5 * time.Second}

	co := &ContainerOrchestrator{
		allowedNetworks: []*net.IPNet{private10, private172, private192},
		breakers:        make(map[string]*CircuitBreaker),
		resolvedCache:   make(map[string]net.IP),
	}

	transport := &http.Transport{
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			host, port, err := net.SplitHostPort(addr)
			if err != nil {
				return nil, err
			}
			// Re-resolve and validate at connection time to prevent DNS rebinding
			ips, err := net.LookupHost(host)
			if err != nil {
				return nil, fmt.Errorf("DNS resolution failed at connect time: %w", err)
			}
			var validIP net.IP
			for _, ipStr := range ips {
				ip := net.ParseIP(ipStr)
				if ip != nil && co.isAllowedIP(ip) {
					validIP = ip
					break
				}
			}
			if validIP == nil {
				return nil, fmt.Errorf("no allowed IP found for %s at connection time", host)
			}
			return dialer.DialContext(ctx, network, net.JoinHostPort(validIP.String(), port))
		},
	}

	co.httpClient = &http.Client{Timeout: 5 * time.Second, Transport: transport}
	return co
}

func (co *ContainerOrchestrator) isAllowedIP(ip net.IP) bool {
	for _, network := range co.allowedNetworks {
		if network.Contains(ip) {
			return true
		}
	}
	return false
}

// validateHealthPath ensures the user-supplied path is a safe, absolute URL path
// and does not contain control characters or attempts to inject a host/authority
// or query manipulation into the request line.
func validateHealthPath(path string) error {
	if !strings.HasPrefix(path, "/") {
		return fmt.Errorf("health path must be an absolute path starting with '/'")
	}
	if strings.HasPrefix(path, "//") {
		return fmt.Errorf("health path must not begin with '//'")
	}
	for _, r := range path {
		if r < 0x20 || r == 0x7f {
			return fmt.Errorf("health path contains control characters")
		}
	}
	if strings.ContainsAny(path, " \t\r\n#@\\") {
		return fmt.Errorf("health path contains disallowed characters")
	}
	return nil
}

func (co *ContainerOrchestrator) validateEndpoint(endpoint ServiceEndpoint) (net.IP, error) {
	ips, err := net.LookupHost(endpoint.Host)
	if err != nil {
		return nil, fmt.Errorf("DNS resolution failed: %w", err)
	}
	if len(ips) == 0 {
		return nil, fmt.Errorf("no IPs resolved for host")
	}
	ip := net.ParseIP(ips[0])
	if ip == nil {
		return nil, fmt.Errorf("invalid IP address resolved")
	}
	if !co.isAllowedIP(ip) {
		return nil, fmt.Errorf("IP %s not in allowed container networks", ip.String())
	}
	co.cacheMu.Lock()
	co.resolvedCache[endpoint.Host] = ip
	co.cacheMu.Unlock()
	return ip, nil
}

func (co *ContainerOrchestrator) getBreaker(key string) *CircuitBreaker {
	co.mu.RLock()
	cb, exists := co.breakers[key]
	co.mu.RUnlock()
	if !exists {
		co.mu.Lock()
		cb = NewCircuitBreaker(3, 30*time.Second)
		co.breakers[key] = cb
		co.mu.Unlock()
	}
	return cb
}

func (co *ContainerOrchestrator) HealthCheck(ctx context.Context, endpoint ServiceEndpoint) (map[string]interface{}, error) {
	if err := validateHealthPath(endpoint.HealthPath); err != nil {
		return nil, err
	}

	resolvedIP, err := co.validateEndpoint(endpoint)
	if err != nil {
		return nil, err
	}

	breakerKey := fmt.Sprintf("%s:%d", resolvedIP.String(), endpoint.Port)
	cb := co.getBreaker(breakerKey)

	if !cb.Allow() {
		return nil, fmt.Errorf("circuit breaker open for %s", breakerKey)
	}

	// Use resolved IP directly to prevent DNS rebinding between validation and connection
	url := fmt.Sprintf("http://%s:%d%s", resolvedIP.String(), endpoint.Port, endpoint.HealthPath)

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		cb.RecordFailure()
		return nil, err
	}
	// Set Host header for virtual hosting support
	req.Host = fmt.Sprintf("%s:%d", endpoint.Host, endpoint.Port)

	resp, err := co.httpClient.Do(req)
	if err != nil {
		cb.RecordFailure()
		return nil, err
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		cb.RecordFailure()
		return nil, fmt.Errorf("health check failed with status %d", resp.StatusCode)
	}

	cb.RecordSuccess()
	var result map[string]interface{}
	if err := json.NewDecoder(resp.Body).Decode(&result); err != nil {
		return nil, err
	}
	return result, nil
}

func (co *ContainerOrchestrator) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Limit request body size to prevent memory-exhaustion DoS.
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20)

	var endpoint ServiceEndpoint
	if err := json.NewDecoder(r.Body).Decode(&endpoint); err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	if endpoint.Port < 1 || endpoint.Port > 65535 {
		http.Error(w, "invalid port", http.StatusBadRequest)
		return
	}

	if endpoint.HealthPath == "" {
		endpoint.HealthPath = "/health"
	}

	result, err := co.HealthCheck(r.Context(), endpoint)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadGateway)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(result)
}
